// The text of every line crew draws. Pure, no mods API: register.ts only arranges these
// strings into elements.

import { formatClock, formatTokens, formatUsd, shortModel, totalTokens, type Price } from './pricing.ts'
import { counts, estimate, run, type AgentRow, type AgentStatus, type Roster } from './roster.ts'

/** crew's one accent, used only for what is live. */
export const ACCENT = '#9B7BEA'

/** The running dot's pulse, one step per animation frame. `○` means idle, so it is not in it. */
export const DOTS: readonly string[] = ['●', '●', '◉', '◉']

export const FINISHED_CAP = 50

export const EMPTY_TEXT = 'No subagents yet — they appear here when Claude delegates work.'

/** The idle line once every agent so far has finished. */
export const QUIET_TEXT = 'All quiet — new subagents appear here when Claude delegates work.'

const SEP = ' · '

// C0 and C1 controls, DEL and the Unicode line and paragraph separators. A surface refuses a
// whole tree whose text holds a control character, so none is ever drawn.
const CONTROL = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g

// Marks, joiners and variation selectors take no cell of their own.
const ZERO_WIDTH = /^[\p{Mn}\p{Me}\u200b-\u200f\ufe00-\ufe0f]$/u
// East Asian wide and fullwidth ranges: two cells each in a terminal.
const WIDE =
  /^[\u1100-\u115f\u2329\u232a\u2e80-\u303e\u3041-\u33ff\u3400-\u4dbf\u4e00-\u9fff\ua000-\ua4cf\ua960-\ua97f\uac00-\ud7a3\uf900-\ufaff\ufe10-\ufe19\ufe30-\ufe6f\uff00-\uff60\uffe0-\uffe6\u{20000}-\u{3fffd}]$/u
const PICTOGRAPH = /^\p{Extended_Pictographic}$/u
const EMOJI = /^\p{Emoji_Presentation}$/u
const EMOJI_VS16 = /^\p{Emoji}\ufe0f$/u

// What widths are counted by: a character, with the VS16 (U+FE0F) right after it if any.
const UNITS = /[^\ufe0f]\ufe0f?|\ufe0f/gu
const unitsOf = (s: string): string[] => s.match(UNITS) ?? []

function cellsOf(unit: string): number {
  // A VS16 asks for the symbol before it to be drawn as an emoji (⚠️, ✔️): two cells.
  if (EMOJI_VS16.test(unit)) return 2
  const ch = String.fromCodePoint(unit.codePointAt(0)!)
  if (ZERO_WIDTH.test(ch)) return 0
  // Emoji drawn as emoji by default are wide (✅ ⚡ 🐛), and the rest past U+1F000; older
  // symbols (©, ✓, ●) are one cell unless asked otherwise.
  if (EMOJI.test(ch) || (ch.codePointAt(0)! >= 0x1f000 && PICTOGRAPH.test(ch))) return 2
  return WIDE.test(ch) ? 2 : 1
}

/** How many terminal cells `s` takes: two for wide characters and emoji, none for marks. */
export function widthOf(s: string): number {
  let w = 0
  for (const u of unitsOf(s)) w += cellsOf(u)
  return w
}

/**
 * Cuts to `width` cells with a trailing `…`, never splitting a character (or a symbol from
 * its VS16). Control characters become spaces, so whatever it returns is safe to draw.
 */
export function truncate(s: string, width: number): string {
  if (width <= 0) return ''
  const clean = s.replace(CONTROL, ' ')
  if (widthOf(clean) <= width) return clean
  let out = ''
  let w = 0
  for (const u of unitsOf(clean)) {
    const c = cellsOf(u)
    if (w + c > width - 1) break
    out += u
    w += c
  }
  return out + '…'
}

/**
 * Text from outside crew (a description, an agent type, a tool name) made fit to keep:
 * one line, runs of whitespace and control characters as one space, at most `max` cells.
 */
export function oneLine(s: string, max = 200): string {
  return truncate(String(s).replace(CONTROL, ' ').replace(/\s+/g, ' ').trim(), max)
}

/** One part of a ` · ` line; parts with a `drop` rank go first, lowest first, when room is short. */
export type Part = { text: string; drop?: number }

/**
 * Joins `parts` with ` · ` in at most `width` cells. Whole parts go before anything is cut:
 * droppable ones, lowest `drop` first; only a line still too wide is truncated.
 */
export function fit(parts: readonly Part[], width: number): string {
  let kept = parts.slice()
  const line = () => kept.map((p) => p.text).join(SEP)
  while (widthOf(line()) > width) {
    let at = -1
    kept.forEach((p, i) => {
      if (p.drop !== undefined && (at < 0 || p.drop < kept[at]!.drop!)) at = i
    })
    if (at < 0) break
    kept = kept.filter((_, i) => i !== at)
  }
  return truncate(line(), width)
}

/** `1 running · 15 done · 2 failed`, zero parts left out; `idle` when all are zero. */
export function headerFacts(c: { running: number; done: number; failed: number; stopped?: number }): string {
  const parts: string[] = []
  if (c.running > 0) parts.push(`${c.running} running`)
  if (c.done > 0) parts.push(`${c.done} done`)
  if (c.failed > 0) parts.push(`${c.failed} failed`)
  if ((c.stopped ?? 0) > 0) parts.push(`${c.stopped} stopped`)
  return parts.length > 0 ? parts.join(SEP) : 'idle'
}

/**
 * `Explore · haiku 4.5 · high · step 7 · Bash`: the model, effort and last tool when known.
 * Short of room, the last tool goes first, then the effort.
 */
export function metaLine(a: AgentRow, width: number): string {
  const parts: Part[] = [{ text: a.type }]
  if (a.model !== '') parts.push({ text: shortModel(a.model) })
  if (a.effort) parts.push({ text: a.effort, drop: 2 })
  parts.push({ text: a.steps > 0 ? `step ${a.steps}` : 'starting' })
  if (a.lastTool) parts.push({ text: a.lastTool, drop: 1 })
  return fit(parts, width)
}

const clamp = (p: number): number => (Number.isFinite(p) ? Math.min(100, Math.max(0, p)) : 0)

/** A thin gauge: `━` for the filled part, `─` for the track. */
export function bar(percent: number, width: number): { filled: string; track: string } {
  const w = Math.max(0, Math.floor(width))
  const n = Math.round((clamp(percent) / 100) * w)
  return { filled: '━'.repeat(n), track: '─'.repeat(w - n) }
}

/** The context percentage as shown: whole, held to 0–100. */
export function ctxPercent(percent: number): number {
  return Math.round(clamp(percent))
}

export function ctxLabel(percent: number): string {
  return `ctx ${ctxPercent(percent)}%`
}

/** The gauge's height where it is a picture, in CSS pixels. */
export const GAUGE_PX = 3

/** The gauge's track, and its filled part once the agent has ended: a middle grey, for dark and light themes alike. */
export const TRACK = '#8A877F'

/**
 * The gauge as a picture, for the surfaces that draw `Svg` (the Desktop app, VS Code,
 * mobile), where a row of `━` comes from a wider fallback font and wraps: a track
 * GAUGE_PX tall with round ends, and the filled part over it, the accent while the agent
 * runs. The markup is wider than any pane, so the picture takes its whole slot; its parts
 * are in percent of it, so they stretch with the slot and the ends stay round.
 */
export function gaugeSvg(percent: number, lit: boolean): string {
  const p = Math.round(clamp(percent) * 10) / 10
  const rect = (w: string, fill: string, more = '') => `<rect width="${w}" height="${GAUGE_PX}" rx="${GAUGE_PX / 2}" fill="${fill}"${more}/>`
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="4000" height="${GAUGE_PX}">` +
    rect('100%', TRACK, ' fill-opacity="0.3"') +
    (p > 0 ? rect(`${p}%`, lit ? ACCENT : TRACK) : '') +
    '</svg>'
  )
}

const usdOrDash = (usd: number | null): string => (usd === null ? '—' : formatUsd(usd, true))
const elapsed = (a: AgentRow, now: number): string => formatClock((a.endedAt ?? now) - a.startedAt)

/**
 * `209.0k tok · 3 tools · ≈$0.04 · 5:35`; the clock stops when the agent ends. Short of
 * room, the tool count goes first, then the tokens: the cost and the time stay.
 */
export function statsLine(a: AgentRow, now: number, usd: number | null, width = Infinity): string {
  const parts: Part[] = [{ text: `${formatTokens(totalTokens(a.tokens))} tok`, drop: 2 }]
  if (a.tools > 0) parts.push({ text: `${a.tools} ${a.tools === 1 ? 'tool' : 'tools'}`, drop: 1 })
  parts.push({ text: usdOrDash(usd) }, { text: elapsed(a, now) })
  return fit(parts, width)
}

// The cells of a Finished row's right side, in column order: model, tokens, cost, time. The
// model's is empty when it is not known.
function finishedCells(a: AgentRow, usd: number | null): string[] {
  return [
    a.model !== '' ? shortModel(a.model) : '',
    formatTokens(totalTokens(a.tokens)),
    usdOrDash(usd),
    elapsed(a, a.endedAt ?? a.startedAt),
  ]
}

/** The right side of a Finished row on its own: `haiku 4.5 · 52.0k · ≈$0.31 · 2:10`. */
export function finishedRight(a: AgentRow, usd: number | null): string {
  return finishedCells(a, usd).filter((c) => c !== '').join(SEP)
}

// The columns of that right side: the model flush left, the numbers flush right. Short of
// room they go lowest `drop` first (the model, then the tokens, then the time); the cost stays.
const FINISHED_COLUMNS: readonly { flushRight: boolean; drop?: number }[] = [
  { flushRight: false, drop: 0 },
  { flushRight: true, drop: 1 },
  { flushRight: true },
  { flushRight: true, drop: 2 },
]

/** `s` padded with spaces to `w` cells, in front when `flushRight`. */
function pad(s: string, w: number, flushRight: boolean): string {
  const gap = ' '.repeat(Math.max(0, w - widthOf(s)))
  return flushRight ? gap + s : s + gap
}

/**
 * The Finished rows as a table, each `✓ <title> <right>` in `width` cells. A column of the
 * right side is as wide as its widest cell, so the `·` line up from row to row. The longest
 * title keeps up to 16 cells (all of a shorter one): while it would get fewer, the columns
 * drop for every row alike, the model first, then the tokens, then the time. The cost stays.
 */
export function finishedLines(rows: readonly { a: AgentRow; usd: number | null }[], width: number): { title: string; right: string }[] {
  const cells = rows.map(({ a, usd }) => finishedCells(a, usd))
  // A column nothing fills (no row knows its model) takes no room, not even its separator.
  let cols = FINISHED_COLUMNS.map((c, i) => ({ ...c, i, w: Math.max(...cells.map((r) => widthOf(r[i]!))) })).filter((c) => c.w > 0)
  const taken = () => cols.reduce((n, c) => n + c.w, 0) + widthOf(SEP) * (cols.length - 1)
  const want = Math.max(...rows.map(({ a }) => Math.min(widthOf(a.description || a.type), 16)))
  // The cost has no rank and is never empty: with more than one column left, one can go.
  while (cols.length > 1 && width - 3 - taken() < want) {
    const gone = cols.filter((c) => c.drop !== undefined).reduce((lo, c) => (c.drop! < lo.drop! ? c : lo))
    cols = cols.filter((c) => c !== gone)
  }
  const room = Math.max(0, width - 3 - Math.min(want, 6))
  return rows.map(({ a }, r) => {
    const right = truncate(cols.map((c) => pad(cells[r]![c.i]!, c.w, c.flushRight)).join(SEP), room)
    return { title: truncate(a.description || a.type, Math.max(0, width - 3 - widthOf(right))), right }
  })
}

/**
 * The title over the agent cards, counting every card under it: `RUNNING · 1 · JUST
 * FINISHED · 2` while some celebrate their end, `JUST FINISHED · 1` when none runs. Short
 * of room, the celebrating count goes first.
 */
export function runningTitle(running: number, ended: number, width = Infinity): string {
  const parts: Part[] = []
  if (running > 0 || ended === 0) parts.push({ text: `RUNNING · ${running}` })
  if (ended > 0) parts.push({ text: `JUST FINISHED · ${ended}`, drop: running > 0 ? 1 : undefined })
  return fit(parts, width)
}

/** A stat card: `label` names it; `title` is what it shows when the card has room for it. */
export type Card = { label: string; title: string; value: string }

/**
 * The three stat cards, totals of the whole session: the main loop with its subagents.
 * Claude Code's real session cost wins; else crew's estimate, marked ≈.
 */
export function cards(input: { realUsd: number | null; estUsd: number | null; tokens: number; sessionMs: number }): Card[] {
  const costValue = input.realUsd !== null ? formatUsd(input.realUsd, false) : input.estUsd !== null ? formatUsd(input.estUsd, true) : '—'
  return [
    { label: 'Cost', title: 'Session cost', value: costValue },
    { label: 'Tokens', title: 'Session tokens', value: formatTokens(input.tokens) },
    { label: 'Time', title: 'Session time', value: formatClock(input.sessionMs) },
  ]
}

/**
 * The cards on one line, for panes too narrow for three boxes: `Cost $0.41 · Tokens 206.5k ·
 * Time 12:18`, or `$0.41 · 206.5k tok · 12:18` when that does not fit either.
 */
export function cardsLine(list: { label: string; value: string }[], width = Infinity): string {
  const full = list.map((c) => `${c.label} ${c.value}`).join(SEP)
  if (widthOf(full) <= width) return full
  return truncate(list.map((c) => (c.label === 'Tokens' ? `${c.value} tok` : c.value)).join(SEP), width)
}

/**
 * The band: `2 running · 1 done · 0:42 · ≈$0.18`, over every agent of the run (since the
 * band appeared), the ones already filed under Finished too. The clock runs from the run's
 * first spawn and stops at its last end once nothing runs. Short of room, the counts of
 * agents that ended go first (while any still runs), then the clock.
 */
export function bandFacts(r: Roster, now: number, overrides: Record<string, Price>, width = Infinity): string {
  const agents = run(r, now)
  const c = counts({ ...r, agents })
  const ended = c.running > 0 ? 1 : undefined
  const parts: Part[] = []
  if (c.running > 0) parts.push({ text: `${c.running} running` })
  if (c.done > 0) parts.push({ text: `${c.done} done`, drop: ended })
  if (c.failed > 0) parts.push({ text: `${c.failed} failed`, drop: ended })
  if (c.stopped > 0) parts.push({ text: `${c.stopped} stopped`, drop: ended })
  if (parts.length === 0) parts.push({ text: 'idle' })
  if (agents.length > 0) {
    const start = Math.min(...agents.map((a) => a.startedAt))
    const end = c.running > 0 ? now : Math.max(...agents.map((a) => a.endedAt ?? now))
    parts.push({ text: formatClock(end - start), drop: 2 })
  }
  let usd: number | null = null
  for (const a of agents) {
    const e = estimate(a, overrides)
    if (e !== null) usd = (usd ?? 0) + e
  }
  if (usd !== null) parts.push({ text: formatUsd(usd, true) })
  return fit(parts, width)
}

/** An agent's status glyph and its color: the accent while running, theme keys after. */
export function glyphOf(status: AgentStatus, frame: number): { char: string; color: string } {
  if (status === 'done') return { char: '✓', color: 'success' }
  if (status === 'failed') return { char: '✗', color: 'error' }
  if (status === 'stopped') return { char: '■', color: 'warning' }
  return { char: DOTS[frame % DOTS.length]!, color: ACCENT }
}

/**
 * The Finished section's fold button: `Collapse` or `Expand`, or `Hide` or `Show` when the
 * section's title and the full label don't fit the pane's width together.
 */
export function foldLabel(count: number, collapsed: boolean, width: number): string {
  const long = collapsed ? 'Expand' : 'Collapse'
  if (widthOf(`FINISHED · ${count}`) + 1 + widthOf(`c: ${long}`) <= width) return long
  return collapsed ? 'Show' : 'Hide'
}

